do $$
declare
  v_city uuid; place_count integer; route_count integer;
begin
  select id into v_city from public.cities where slug='krakow';
  select count(*) into place_count from public.places where city_id=v_city and status='published' and visibility='public';
  select count(*) into route_count from public.routes where city_id=v_city and route_type='editorial' and status='published' and visibility='public';
  if place_count <> 208 then raise exception 'Kraków place parity failed: got %, expected 208',place_count; end if;
  if route_count <> 15 then raise exception 'Kraków route parity failed: got %, expected 15',route_count; end if;
end $$;
